day=input("Breakfast Recommendations ~ Type the current day of the week, all lowercase: ")
if day=="mon" or day=="monday":
    print("Start your day with a bowl of cereal! It's quick, easy, and provides about 150 to 350 calories and about 12g of protein. Prefer something different? Try bacon and eggs for about 300 to 385 calories and about 18g of protein. Nutrient amounts all depend on the portion size.")
elif day=="tues" or day=="tuesday":
    print("Enjoy a bagel with nutella today. Delicious! A typical serving contains 450 to 550 calories and provides approximately 11 grams of protein. Nutrition amount varies based on the portion size.")
elif day=="wed" or day=="wednesday":
    print("Start your day with scrambled eggs and a slice of toast. Simple and filling! It provides around 300 to 450 calories and about 18 grams of protein.")
elif day=="thurs" or day=="thursday":
    print("Enjoy some avocado toast with a sunny-side-up egg today. Healthy and delicious! It provides around 250 to 350 calories and about 12 grams of protein. Want another option? Mouth-watering sausages. They provide 80 to 120 calories and about 20 grams of protein, per stick, depending on the portion size.")
elif day=="fri" or day=="friday":
    print("Boost your day with a bowl of oatmeal mixed with nuts and fruits of your choice. It offers 150 to 300 calories and around 12 grams of protein.The nutrional value will vary based on how much you eat.")
elif day=="sat" or day=="saturday":
    print("Treat yourself to pancakes with syrup and fruit today. Yum! This breakfast provides around 500 to 600 calories and about 12 grams of protein. The nutritional numbers depend on how much you eat.")
elif day =="sun" or day=="sunday":
    print("Have an omelet today, recommended with spinach for a bit of nutrition. A tasty and nutritious choice! It provides around 160 to 200 calories and about 14 grams of protein, depending on the portion size.")
else:
    print("Hmm... we couldn’t find that. Double-check your spelling and give it another try!")